/**
 * Published WS2001 firmware releases (public/firmware/ws2001/manifest.json),
 * generated by scripts/update-ws2001-manifest.mjs.
 */

import { sha256Hex } from '../flasher/hashing';
import { parseWs2001DfuPackage, type Ws2001DfuPackage } from './ws2001Dfu';

export const WS2001_MANIFEST_URL = '/firmware/ws2001/manifest.json';

export interface Ws2001Release {
  version: string; // "4.5"
  label: string; // "V4.5"
  fw_version: number; // DFU application version (major*10+minor)
  file: string;
  bytes: number;
  sha256: string;
  image_bytes: number;
  image_sha256: string;
  git_commit?: string;
  built_at?: string;
}

export interface Ws2001Manifest {
  schema: 1;
  hardware: 'WS2001';
  latest: string;
  releases: Ws2001Release[];
}

export function validateWs2001Manifest(raw: unknown): Ws2001Manifest {
  const m = raw as Partial<Ws2001Manifest> | null;
  if (!m || m.schema !== 1 || m.hardware !== 'WS2001') throw new Error('Invalid WS2001 firmware manifest');
  if (!Array.isArray(m.releases) || m.releases.length === 0) throw new Error('WS2001 manifest lists no releases');
  for (const r of m.releases) {
    if (!r.file?.startsWith('/firmware/ws2001/') || !/^[0-9a-f]{64}$/i.test(r.sha256) || !Number.isInteger(r.fw_version)) {
      throw new Error(`WS2001 release ${r.version ?? '?'} is malformed`);
    }
  }
  if (!m.releases.some((r) => r.version === m.latest)) throw new Error('WS2001 manifest "latest" is not listed');
  return m as Ws2001Manifest;
}

export async function fetchWs2001Manifest(fetchImpl: typeof fetch = fetch): Promise<Ws2001Manifest> {
  const res = await fetchImpl(WS2001_MANIFEST_URL, { cache: 'no-store' });
  if (!res.ok) throw new Error(`Could not load the WS2001 firmware list (HTTP ${res.status})`);
  return validateWs2001Manifest(await res.json());
}

export function latestRelease(m: Ws2001Manifest): Ws2001Release {
  return m.releases.find((r) => r.version === m.latest)!;
}

/** Download a release and check its SHA-256, signature and target before it is offered for install. */
export async function downloadWs2001Release(
  r: Ws2001Release,
  fetchImpl: typeof fetch = fetch,
): Promise<Ws2001DfuPackage> {
  const res = await fetchImpl(r.file, { cache: 'no-store' });
  if (!res.ok) throw new Error(`Could not download ${r.label} (HTTP ${res.status})`);
  const bytes = new Uint8Array(await res.arrayBuffer());
  if ((await sha256Hex(bytes)).toLowerCase() !== r.sha256.toLowerCase()) {
    throw new Error(`${r.label} download is corrupted (SHA-256 mismatch)`);
  }
  const pkg = await parseWs2001DfuPackage(bytes);
  if (pkg.initPacket.fwVersion !== r.fw_version) throw new Error(`${r.label} package version does not match the manifest`);
  return pkg;
}

/** "V4.5" / "4.5" / "V3.13" -> [major, minor]; null when unknown. */
export function parseStationVersion(v: string | null | undefined): [number, number] | null {
  const m = (v ?? '').match(/(\d+)\.(\d+)/);
  return m ? [parseInt(m[1], 10), parseInt(m[2], 10)] : null;
}

/** True when the station runs an older firmware than `latest` (unknown versions count as outdated). */
export function isOutdated(station: string | null | undefined, latest: string): boolean {
  const s = parseStationVersion(station);
  const l = parseStationVersion(latest);
  if (!l) return false;
  if (!s) return true;
  return s[0] < l[0] || (s[0] === l[0] && s[1] < l[1]);
}
